47	/**
48	 * Renders the list of available deferred tools. This is placed in the global conversation
49	 * context (not the system prompt) so the list appears at the start of a new conversation.
50	 * Self-gates on `endpoint.supportsToolSearch` — returns nothing if tool search is unsupported,
51	 * if no tools are available, or if there are no deferred tools.
52	 */
53	export class DeferredToolListReminder extends PromptElement<DeferredToolListReminderProps> {
54		constructor(
55			props: PromptElementProps<DeferredToolListReminderProps>,
56			@IToolDeferralService private readonly toolDeferralService: IToolDeferralService,
