62			const endpoint = sizing.endpoint as IChatEndpoint | undefined;
63	
64			if (!endpoint?.supportsToolSearch || !this.props.availableTools) {
65				return;
66			}
67	
68			const deferredTools = getDeferredToolNames(this.props.availableTools, this.toolDeferralService);
69			if (deferredTools.length === 0) {
